sys_variable_value.value:
(function execute(inputs, outputs) {
var novoParentId = inputs.sysID27;
var mrvsID = inputs.mrvsID;

// Cria uma instância de GlideRecord para a tabela 'sc_multi_row_question_answer'
var grSMRQA = new GlideRecord('sc_multi_row_question_answer');

// Consulta todas as linhas que correspondem ao filtro, neste caso:
// - Começam com o prefixo especificado em parent_id
// - Estão associadas ao conjunto de variáveis especificado
grSMRQA.addEncodedQuery("parent_idSTARTSWITH"+ inputs.sysID26  +"^variable_set=" + mrvsID);
grSMRQA.orderBy('row_index');
grSMRQA.query();

// Itera sobre cada registro encontrado
while (grSMRQA.next()) {
    // Cria uma nova instância para um novo registro
    var novoRegistro = new GlideRecord('sc_multi_row_question_answer');
    novoRegistro.initialize();

    // Copia todos os campos relevantes do registro atual para o novo registro,
    // mas substitui o parent_id pelo novo sys_id especificado.
    novoRegistro.setValue('item_option_new', grSMRQA.getValue('item_option_new'));
    novoRegistro.setValue('parent_id', novoParentId);  // Define o novo parent_id
    novoRegistro.setValue('parent_table_name', grSMRQA.getValue('parent_table_name'));
    novoRegistro.setValue('question_answer', grSMRQA.getValue('question_answer'));
    //novoRegistro.setValue('row_index', grSMRQA.getValue('row_index'));
    novoRegistro.setValue('row_index', '090909090909');
    novoRegistro.setValue('sc_item_option', grSMRQA.getValue('sc_item_option'));
    novoRegistro.setValue('value', grSMRQA.getValue('value'));
    novoRegistro.setValue('variable_set', grSMRQA.getValue('variable_set'));

    // Insere o novo registro na tabela
    novoRegistro.insert();
}
})(inputs, outputs);

